-- Enrichir les notes de l'héliotropine avec les données réglementaires de l'article NEZ
UPDATE molecules 
SET notes = CONCAT(COALESCE(notes, ''), 
  '\n\n**Statut réglementaire (2024-2026)** : En 2024, le CER de l\'ECHA a demandé le classement comme substance reprotoxique CMR 1B. Un dossier de dérogation a été déposé par un consortium cosmétique/parfumerie en juin 2025 (IFRA, RIFM). Le facteur de sécurité calculé par le RIFM est >33 000 pour l\'exposition réelle en parfumerie. Synthèse industrielle depuis 1879 (Schimmel & Co). Source : NEZ, J. Mignot, jan. 2026.')
WHERE id = 90071;

-- Enrichir les notes de Boswellia sacra avec les données du Wadi Dawkah
UPDATE plants
SET notes = CONCAT(COALESCE(notes, ''),
  '\n\n**Wadi Dawkah (2022-2026)** : 1400 ha classés UNESCO depuis 2000 (Dhofar, Oman). Relance de la filière encens par Amouage + ministère omanais du Tourisme en 2022. Objectif : HE traçable "de l\'arbre jusqu\'à la larme". 5000 arbres géolocalisés avec QR code individuel. Menace principale : dromadaires (consomment les feuilles). Depuis avril 2023 : irrigation réduite pour régulation naturelle. Source : NEZ, B. Boisserie, jan. 2026.')
WHERE id = 690259;

SELECT id, name, LEFT(notes, 200) as notes_preview FROM molecules WHERE id = 90071;
SELECT id, name, LEFT(notes, 200) as notes_preview FROM plants WHERE id = 690259;

